// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_9", entity: "dlt_noticePopupList", countIds: [], cells: [{ childId: "ipt_notiDd", fn: function (v, i) { return String(v("notiDd")); } }, { childId: "ipt_endDd", fn: function (v, i) { return String(v("endDd")); } }] },
        { genId: "c_foreach_85", entity: "dlt_noticeList", countIds: [], cells: [{ childId: "btn_noticeView", fn: function (v, i) { return String(String(String(v("contnTitle"))).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')); } }, { childId: "__rc0", fn: function (v, i) { return String(v("regDate")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.showMessage();
        if ('null' === 'Y') {
            $c.util.getComponent("download_page").setStyle("display", "");
            $c.util.getComponent('ipt_dnldGrpTpCd').setValue('null');
        } else {
            $c.util.getComponent("download_page").setStyle("display", "none");
        }
        const fm = (document.form || { elements: [] });
        let _cnt = 0;
        if (fm.contn_id != null) {
            _cnt = fm.contn_id.length;
            if (_cnt == null) {
                if (scwin.getCookie("isinPopupJsp") === "") {
                    var startdd = $c.util.getComponent('ipt_notiDd').getValue() + "";
                    var enddd = $c.util.getComponent('ipt_endDd').getValue() + "";
                    var fromDate;
                    var toDate;
                    if (startdd !== "undefined") {
                        fromDate = new Date(startdd.substring(0, 4), scwin.LPAD(parseInt(startdd.substring(4, 6)) - 1), startdd.substring(6, 8), "09", "00");
                    }
                    if (enddd !== "undefined") {
                        toDate = new Date(enddd.substring(0, 4), scwin.LPAD(parseInt(enddd.substring(4, 6)) - 1), enddd.substring(6, 8), "19", "59");
                    }
                    if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                        await scwin.popupJsp();
                    }
                }
            } else {
                var startdd;
                var enddd;
                var fromDate;
                var toDate;
                for (let i = 0; i < _cnt; i++) {
                    if (scwin.getCookie("isinPopupJsp" + fm.contn_id[i].value) === "") {
                        startdd = $c.util.getComponent('dlt_noticePopupList').getCellData(i, 'notiDd');
                        enddd = $c.util.getComponent('dlt_noticePopupList').getCellData(i, 'endDd');
                        if (startdd !== "undefined") {
                            fromDate = new Date(startdd.substring(0, 4), scwin.LPAD(parseInt(startdd.substring(4, 6)) - 1), startdd.substring(6, 8), "09", "00");
                        }
                        if (enddd !== "undefined") {
                            toDate = new Date(enddd.substring(0, 4), scwin.LPAD(parseInt(enddd.substring(4, 6)) - 1), enddd.substring(6, 8), "19", "59");
                        }
                        if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                            await scwin.popupJspList(i);
                        }
                    }
                }
            }
        }
        if (scwin.getCookie("isinPopupJsp1") === "") {
            fromDate = new Date("2018", "11", "03", "17", "00");
            toDate = new Date("2019", "02", "30", "23", "59");
            if (scwin.precheckBeforeOpenNotice(fromDate, toDate)) {
                await scwin.popupJsp1();
            }
        }
        await scwin.showMessage();
        if (scwin.IEVersionCheck() > 10) {
            history.pushState(null, null, location.href);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf00000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(notice vs register) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_loginForm = { action: "", method: 'post', target: '' };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00000.onpageload' });
    }
};


