/**
 * @method
 * @name scwin.LPAD
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.LPAD = function (val) {
    /* sdd-asis-lifecycle:begin LPAD — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (val < 10) {
        return "0" + "" + val;
    } else {
        return val;
    }
    /* sdd-asis-lifecycle:end */
};


