/**
 * @method
 * @name scwin.precheckBeforeOpenNotice
 * @author Inswave
 * @date 2026. 09. 29
 * @param fromDate toDate
 * @returns
 * @hidden N
*/
scwin.precheckBeforeOpenNotice = function (fromDate, toDate) {
    /* sdd-asis-lifecycle:begin precheckBeforeOpenNotice — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const curDate = new Date();
    if (fromDate <= curDate && curDate <= toDate) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


