    lngLeft = (screen.width - lngWidth) / 2;
    strOptions = strOptions + ", width=" + lngWidth + ", height=" + lngHeight + ", top=" + lngTop + ", left=" + lngLeft;
    const newWin = $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(strPageURL), { id: strWindowName }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.IEVersionCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.IEVersionCheck = function () {
    /* sdd-asis-lifecycle:begin IEVersionCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let word;
    let version = "N/A";
    const agent = navigator.userAgent.toLowerCase();
    const name = navigator.appName;
    if (name === "Microsoft Internet Explorer") {
        word = "msie ";
    } else {
        if (agent.search("trident") > -1) {
            word = "trident/.*rv:";
        } else {
            if (agent.search("edge/") > -1) {
                word = "edge/";
            }
        }
    }
    const reg = new RegExp(word + "([0-9]{1,})(\\.{0,}[0-9]{0,1})");
    if (reg.exec(agent) != null) {
        version = RegExp.$1 + RegExp.$2;
    }
    return version;
    /* sdd-asis-lifecycle:end */
};
